for(const side of [-1,1]){const leg=new THREE.Mesh(new THREE.CapsuleGeometry(.14,.37,4,7),team==='yellow'?mat(0xd59f3e):mat(0x399a78));leg.position.set(side*.2,.36,0);leg.castShadow=true;body.add(leg);const boot=new THREE.Mesh(new THREE.BoxGeometry(.31,.17,.4),charcoal);boot.position.set(side*.2,.14,.08);body.add(boot);const arm=new THREE.Mesh(new THREE.CapsuleGeometry(.115,.36,4,7),team==='yellow'?mat(0xffe7a5):mat(0xc5f4df));arm.position.set(side*.48,1.02,.08);arm.rotation.z=side*.45;arm.castShadow=true;body.add(arm)}
const gun=new THREE.Group();const barrel=new THREE.Mesh(new THREE.CylinderGeometry(.09,.12,.67,10),darkIce);barrel.rotation.z=-Math.PI/2;barrel.position.set(.56,1.04,.13);barrel.castShadow=true;gun.add(barrel);const tank=new THREE.Mesh(new THREE.SphereGeometry(.22,10,8),white);tank.scale.set(1,.8,1);tank.position.set(.2,1.1,.14);gun.add(tank);const nozzle=new THREE.Mesh(new THREE.TorusGeometry(.105,.035,7,12),mat(0x43899a));nozzle.rotation.y=Math.PI/2;nozzle.position.set(.91,1.04,.13);gun.add(nozzle);body.add(gun);
const shadow=new THREE.Mesh(new THREE.CircleGeometry(.55,16),mat(0x9ebbc2));shadow.rotation.x=-Math.PI/2;shadow.position.y=.025;root.add(shadow);
const hpGroup=new THREE.Group();const hpBack=new THREE.Mesh(new THREE.BoxGeometry(.9,.1,.06),mat(0x426273));hpBack.position.y=2.55;hpGroup.add(hpBack);const hpFront=new THREE.Mesh(new THREE.BoxGeometry(.84,.065,.07),color);hpFront.position.set(0,2.55,.04);hpGroup.add(hpFront);root.add(hpGroup);
scene.add(root);const f={team,isPlayer,index,root,body,gun,hpFront,hpGroup,hp:100,alive:true,respawn:0,cooldown:Math.random()*.7,ammo:6,reload:0,dir:new THREE.Vector2(team==='yellow'?1:-1,0),speed:isPlayer?6.7:3.1+Math.random()*.6,strafe:Math.random()<.5?-1:1,think:Math.random(),kills:0};root.userData.fighter=f;return f}
const fighters=[];const player=makeFighter('yellow',true,0);player.root.position.set(-10,0,0);fighters.push(player);
for(let i=1;i<5;i++){const f=makeFighter('yellow',false,i);f.root.position.set(-10+Math.random()*2,0,(i-2)*2.1);fighters.push(f)}
for(let i=0;i<5;i++){const f=makeFighter('green',false,i);f.root.position.set(10+Math.random()*2,0,(i-2)*2.1);fighters.push(f)}
const projectiles=[];const ballGeo=new THREE.SphereGeometry(.2,12,10);const trailGeo=new THREE.SphereGeometry(.07,7,6);const snowballMat=mat(0xffffff,.25);const colors={yellow:0xffc43d,green:0x42d9a0};
function launch(shooter,dir){if(!shooter.alive||shooter.cooldown>0)return;if(shooter.ammo<=0){if(!shooter.reload)shooter.reload=1.25;return}shooter.cooldown=shooter.isPlayer?.27:.62+Math.random()*.38;shooter.ammo--;const start=shooter.root.position.clone().add(new THREE.Vector3(dir.x*.78,1.15,dir.y*.78));const mesh=new THREE.Mesh(ballGeo,snowballMat);mesh.castShadow=true;mesh.position.copy(start);scene.add(mesh);const tail=new THREE.Mesh(trailGeo,shooter.team==='yellow'?gold:mint);tail.position.copy(start);scene.add(tail);projectiles.push({mesh,tail,team:shooter.team,owner:shooter,vel:new THREE.Vector3(dir.x,0,dir.y).multiplyScalar(15),life:2.1});if(shooter.isPlayer)updateAmmo()}
function updateAmmo(){const el=document.querySelector('#ammo');el.innerHTML='';for(let i=0;i<6;i++){const n=document.createElement('i');if(i>=player.ammo)n.className='empty';el.append(n)}}
updateAmmo();
const keys={};window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='Space'){player.fireHeld=true}});window.addEventListener('keyup',e=>{keys[e.code]=false;if(e.code==='Space')player.fireHeld=false});
const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2();const groundPlane=new THREE.Plane(new THREE.Vector3(0,1,0),0);let mouseAim=null;
