function bindStick(el,callback,onFire=false){let active=null,origin=null;const knob=el.querySelector('.knob');el.addEventListener('pointerdown',e=>{e.preventDefault();active=e.pointerId;el.setPointerCapture(active);const r=el.getBoundingClientRect();origin={x:r.left+r.width/2,y:r.top+r.height/2};if(onFire)player.fireHeld=true;move(e)});el.addEventListener('pointermove',e=>{if(e.pointerId===active)move(e)});function move(e){const dx=e.clientX-origin.x,dy=e.clientY-origin.y,len=Math.hypot(dx,dy),max=el.clientWidth*.34,k=Math.min(1,max/(len||1));knob.style.left=`calc(50% + ${dx*k}px)`;knob.style.top=`calc(50% + ${dy*k}px)`;callback(dx/(len||1)*Math.min(1,len/max),dy/(len||1)*Math.min(1,len/max),len>9)}function end(e){if(e.pointerId!==active)return;active=null;knob.style.left='50%';knob.style.top='50%';callback(0,0,false);if(onFire)player.fireHeld=false}el.addEventListener('pointerup',end);el.addEventListener('pointercancel',end)}
