function startGame(){if(state==='paused'){state='playing';overlay.classList.add('hidden');return}if(state==='finished'){resetGame()}state='playing';overlay.classList.add('hidden');last=performance.now();showBanner('SNOWBALL FIGHT!','FIRST TO 15 WINS')}
function pauseGame(){if(state==='playing'){state='paused';document.querySelector('.eyebrow').textContent='❄  TAKE A BREATHER  ❄';document.querySelector('.logo').innerHTML='TIME <em>OUT</em>';document.querySelector('.subtitle').textContent='The snowball fight is paused.';document.querySelector('.teams').style.display='none';document.querySelector('.instructions').textContent='Catch your breath, then jump back into the arena.';startBtn.innerHTML='RESUME GAME  ➜';document.querySelector('.note').textContent='YOUR MATCH IS WAITING';overlay.classList.remove('hidden')}else if(state==='paused')startGame()}
startBtn.addEventListener('click',()=>{if(state==='menu'){document.querySelector('.eyebrow').innerHTML='❄ &nbsp; 3D SNOWBALL SHOWDOWN &nbsp; ❄';document.querySelector('.logo').innerHTML='FROST<span>FRONT</span>';document.querySelector('.subtitle').textContent='A 5 vs 5 winter skirmish';document.querySelector('.teams').style.display='flex';document.querySelector('.instructions').innerHTML='Outplay the other squad in a snowy mountain arena. Land snowballs, help your team, and reach <b>15 points</b> before time runs out.';startBtn.innerHTML='ENTER THE ARENA &nbsp;➜';document.querySelector('.note').textContent='WASD + CLICK ON DESKTOP &nbsp;·&nbsp; TOUCH JOYSTICKS ON PHONE / TABLET'}startGame()});pauseBtn.addEventListener('click',pauseGame);
function resetGame(){yellowScore=0;greenScore=0;timeLeft=120;yellowEl.textContent='0';greenEl.textContent='0';for(const f of fighters){f.hp=100;f.alive=true;f.respawn=0;f.ammo=6;f.reload=0;f.cooldown=Math.random()*.4;f.root.visible=true;f.root.position.set(f.team==='yellow'?-10:10,0,(f.index-2)*1.8);f.dir.set(f.team==='yellow'?1:-1,0)}player.kills=0;updateAmmo();state='playing';document.querySelector('.eyebrow').innerHTML='❄ &nbsp; 3D SNOWBALL SHOWDOWN &nbsp; ❄';document.querySelector('.logo').innerHTML='FROST<span>FRONT</span>';document.querySelector('.subtitle').textContent='A 5 vs 5 winter skirmish';document.querySelector('.teams').style.display='flex';startBtn.innerHTML='ENTER THE ARENA &nbsp;➜';document.querySelector('.instructions').innerHTML='Outplay the other squad in a snowy mountain arena. Land snowballs, help your team, and reach <b>15 points</b> before time runs out.';document.querySelector('.note').textContent='WASD + CLICK ON DESKTOP &nbsp;·&nbsp; TOUCH JOYSTICKS ON PHONE / TABLET';overlay.classList.add('hidden')}
function finishGame(){state='finished';const won=yellowScore>greenScore;document.querySelector('.eyebrow').textContent=won?'🏆  VICTORY!  🏆':'❄  MATCH COMPLETE  ❄';document.querySelector('.logo').innerHTML=won?'SNOW <em>HERO</em>':'GOOD <em>GAME</em>';document.querySelector('.subtitle').textContent=`Final score  ${yellowScore}  —  ${greenScore}`;document.querySelector('.teams').style.display='none';document.querySelector('.instructions').textContent=won?'Sunfall takes the mountain! Ready for another round?':'Pineguard got the last laugh. Rally your squad and try again!';startBtn.innerHTML='PLAY AGAIN  ↻';document.querySelector('.note').textContent=`YOU LANDED ${player.kills} ELIMINATION${player.kills===1?'':'S'}`;overlay.classList.remove('hidden')}
function nearestEnemy(f){let target=null,best=Infinity;for(const other of fighters){if(!other.alive||other.team===f.team)continue;const d=f.root.position.distanceToSquared(other.root.position);if(d<best){best=d;target=other}}return target}
function isBlocked(x,z){for(const o of obstacles)if(Math.hypot(x-o.x,z-o.z)<o.r+.4)return true;return false}
function updateFighter(f,dt){if(!f.alive){f.respawn-=dt;if(f.respawn<=0){f.alive=true;f.hp=100;f.ammo=6;f.reload=0;f.root.visible=true;f.root.position.set(f.team==='yellow'?-10:10,0,(f.index-2)*1.8+(Math.random()-.5)*1.5);f.dir.set(f.team==='yellow'?1:-1,0);if(f.isPlayer){healthFill.style.width='100%';healthNum.textContent='100 HP';updateAmmo();showBanner('BACK IN!','YOUR TEAM NEEDS YOU')}}return}
if(f.cooldown>0)f.cooldown-=dt;if(f.reload>0){f.reload-=dt;if(f.reload<=0){f.ammo=6;if(f.isPlayer)updateAmmo()}}
let dx=0,dz=0,target=null;
if(f.isPlayer){dx=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+touchMove.x;dz=(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0)-touchMove.y;const mv=Math.hypot(dx,dz);if(mv>1){dx/=mv;dz/=mv}if(mouseAim)f.dir.copy(mouseAim);else if(touchAim.lengthSq()>.1)f.dir.copy(touchAim).normalize();if(f.fireHeld)launch(f,f.dir);if(mv>.04){const nx=THREE.MathUtils.clamp(f.root.position.x+dx*f.speed*dt,-15.4,15.4),nz=THREE.MathUtils.clamp(f.root.position.z+dz*f.speed*dt,-15.4,15.4);if(!isBlocked(nx,f.root.position.z))f.root.position.x=nx;if(!isBlocked(f.root.position.x,nz))f.root.position.z=nz}}
else{target=nearestEnemy(f);if(target){const vx=target.root.position.x-f.root.position.x,vz=target.root.position.z-f.root.position.z,dist=Math.hypot(vx,vz)||1;f.dir.set(vx/dist,vz/dist);if(dist>7.5){dx=vx/dist;dz=vz/dist}else if(dist<4.2){dx=-vx/dist*.65+(-vz/dist)*f.strafe*.7;dz=-vz/dist*.65+(vx/dist)*f.strafe*.7}else{dx=-vz/dist*f.strafe*.2;dz=vx/dist*f.strafe*.2}const m=Math.hypot(dx,dz)||1;dx/=m;dz/=m;const nx=THREE.MathUtils.clamp(f.root.position.x+dx*f.speed*dt,-15.4,15.4),nz=THREE.MathUtils.clamp(f.root.position.z+dz*f.speed*dt,-15.4,15.4);if(!isBlocked(nx,f.root.position.z))f.root.position.x=nx;else f.strafe*=-1;if(!isBlocked(f.root.position.x,nz))f.root.position.z=nz;const aim=new THREE.Vector2(vx/dist+(Math.random()-.5)*.11,vz/dist+(Math.random()-.5)*.11).normalize();if(dist<17&&Math.random()<dt*1.3)launch(f,aim)}}
const angle=Math.atan2(f.dir.y,f.dir.x);f.body.rotation.y=-angle;f.body.position.y=.045*Math.sin(performance.now()*.007+f.index);f.hpGroup.visible=!f.isPlayer&&f.hp<100;f.hpFront.scale.x=Math.max(.02,f.hp/100);f.hpFront.position.x=-(1-f.hp/100)*.42;
}
function updateProjectiles(dt){for(let i=projectiles.length-1;i>=0;i--){const p=projectiles[i];p.life-=dt;p.mesh.position.addScaledVector(p.vel,dt);p.mesh.position.y=1.12+Math.sin((2.1-p.life)*3)*.13;p.tail.position.copy(p.mesh.position).addScaledVector(p.vel,-.045);let remove=p.life<=0||Math.abs(p.mesh.position.x)>18||Math.abs(p.mesh.position.z)>18;for(const o of obstacles){if(Math.hypot(p.mesh.position.x-o.x,p.mesh.position.z-o.z)<o.r*.83){remove=true;break}}
if(!remove)for(const f of fighters){if(!f.alive||f.team===p.team||f===p.owner)continue;if(Math.hypot(p.mesh.position.x-f.root.position.x,p.mesh.position.z-f.root.position.z)<.68){f.hp-=34;remove=true;if(f.hp<=0){f.hp=0;f.alive=false;f.respawn=2.2;f.root.visible=false;const killer=p.owner;killer.kills++;if(killer.team==='yellow'){yellowScore++;yellowEl.textContent=yellowScore}else{greenScore++;greenEl.textContent=greenScore}if(killer.isPlayer)showBanner('GREAT SHOT!','PINEGUARD DOWN');else if(f.isPlayer)showBanner('TAGGED!','YOU GOT HIT');if(f.isPlayer){healthFill.style.width='0%';healthNum.textContent='0 HP'}if(yellowScore>=15||greenScore>=15)finishGame()}else if(f.isPlayer){healthFill.style.width=`${f.hp}%`;healthNum.textContent=`${f.hp} HP`;showBanner('SPLAT!','KEEP MOVING')} }break}
if(remove){scene.remove(p.mesh,p.tail);projectiles.splice(i,1)}}}
function updateHud(){const secs=Math.max(0,Math.ceil(timeLeft));timerEl.textContent=`${String(Math.floor(secs/60)).padStart(2,'0')}:${String(secs%60).padStart(2,'0')}`;timerEl.style.color=secs<15?'#ff8b79':'white'}
function animate(now){requestAnimationFrame(animate);const dt=Math.min(.04,(now-last)/1000);last=now;if(state==='playing'){timeLeft-=dt;for(const f of fighters)updateFighter(f,dt);updateProjectiles(dt);updateHud();if(timeLeft<=0)finishGame()}if(bannerTimer>0){bannerTimer-=dt;if(bannerTimer<=0)document.querySelector('#banner').classList.remove('show')}
// Soft camera tracking keeps the scout and the changing arena in frame.
const desired=new THREE.Vector3(player.root.position.x*.48+1,19.5,23);camera.position.lerp(desired,.045);camera.lookAt(player.root.position.x*.32,0,0);
for(const p of scene.children){if(p.userData.speed){p.position.y-=p.userData.speed*dt;if(p.position.y<0){p.position.y=12+Math.random()*5;p.position.x=(Math.random()-.5)*38;p.position.z=(Math.random()-.5)*38}}}
renderer.render(scene,camera)}requestAnimationFrame(animate);
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8))});
</script></body></html>

